from __future__ import annotations
import json
import httpx
from . import config
from .models import INTENCOES

_TOOL_NAME = "extrair_dados_cotacao"

_TOOL = {
    "type": "function",
    "function": {
        "name": _TOOL_NAME,
        "description": "Extrai os dados de cotacao de seguro auto e classifica a intencao da mensagem atual do lead.",
        "parameters": {
            "type": "object",
            "properties": {
                "plano_id": {"type": ["string", "null"], "enum": ["essencial", "completo", "premium", None]},
                "idade": {"type": ["integer", "null"]},
                "veiculo_ano": {"type": ["integer", "null"]},
                "cep": {"type": ["string", "null"]},
                "data_inicio": {"type": ["string", "null"], "description": "formato YYYY-MM-DD"},
                "intencao": {"type": "string", "enum": list(INTENCOES)},
            },
            "required": ["intencao"],
        },
    },
}

_SYSTEM = (
    "Voce extrai dados estruturados de conversas de um lead com uma seguradora de veiculos "
    "e classifica a intencao da ultima mensagem do lead. Use so o que estiver explicito no "
    "historico e na mensagem atual, nunca invente valores. Se um dado nao foi informado, "
    "omita o campo. Idade e ano do veiculo devem ser numeros inteiros."
)

_OPENROUTER_URL = "https://openrouter.ai/api/v1/chat/completions"


def _build_prompt(history: list[dict], current_message: str) -> str:
    linhas = [f"{m['sender_role']}: {m['body']}" for m in history]
    linhas.append(f"lead: {current_message}")
    return "Historico da conversa:\n" + "\n".join(linhas)


def extract_and_classify(history: list[dict], current_message: str) -> tuple[dict, str | None]:
    try:
        resp = httpx.post(
            _OPENROUTER_URL,
            headers={
                "Authorization": f"Bearer {config.OPENROUTER_API_KEY}",
                "Content-Type": "application/json",
            },
            json={
                "model": config.OPENROUTER_MODEL,
                "messages": [
                    {"role": "system", "content": _SYSTEM},
                    {"role": "user", "content": _build_prompt(history, current_message)},
                ],
                "tools": [_TOOL],
                "tool_choice": {"type": "function", "function": {"name": _TOOL_NAME}},
            },
            timeout=config.OPENROUTER_TIMEOUT_SECONDS,
        )
        resp.raise_for_status()
        tool_calls = resp.json()["choices"][0]["message"]["tool_calls"]
        data = json.loads(tool_calls[0]["function"]["arguments"])
    except Exception:
        return {}, None

    intencao = data.pop("intencao", None)
    slots = {k: v for k, v in data.items() if v is not None}
    return slots, intencao

from __future__ import annotations
from dataclasses import dataclass, field
from . import config
from .models import ConversationState, QuoteResult, REQUIRED_SLOTS, SLOT_FIELDS


def merge_slots(known: dict, delta: dict) -> dict:
    merged = dict(known)
    for field_name in SLOT_FIELDS:
        if delta.get(field_name) is not None:
            merged[field_name] = delta[field_name]
    return merged


def missing_required(slots: dict) -> list[str]:
    return [f for f in REQUIRED_SLOTS if not slots.get(f)]


@dataclass
class PreDecision:
    action: str
    slots: dict
    stagnation_count: int
    motivo: str | None = None
    missing: list[str] = field(default_factory=list)


def pre_quote_decision(state: ConversationState, intent: str | None, slots_delta: dict) -> PreDecision:
    new_slots = merge_slots(state.slots, slots_delta)

    if intent == "pedindo_humano":
        return PreDecision(action="escalar", slots=new_slots, stagnation_count=state.stagnation_count,
                            motivo="pedido_explicito")

    missing_before = missing_required(state.slots)
    missing_after = missing_required(new_slots)

    if not missing_after:
        return PreDecision(action="cotar", slots=new_slots, stagnation_count=0)

    progress = len(missing_after) < len(missing_before)
    stagnation_count = 0 if progress else state.stagnation_count + 1

    if stagnation_count >= config.STAGNATION_LIMIT:
        return PreDecision(action="escalar", slots=new_slots, stagnation_count=stagnation_count,
                            motivo="estagnacao_coleta", missing=missing_after)

    return PreDecision(action="pedir_dado", slots=new_slots, stagnation_count=stagnation_count, missing=missing_after)


@dataclass
class PostDecision:
    action: str
    motivo: str | None = None


def post_quote_decision(result: QuoteResult) -> PostDecision:
    if result.status == "sucesso":
        return PostDecision(action="responder_cotacao")
    if result.status == "recusada":
        return PostDecision(action="responder_recusa", motivo=result.motivo)
    return PostDecision(action="escalar", motivo="falha_tecnica_persistente")


def build_quote_payload(slots: dict) -> dict:
    payload = {
        "plano_id": slots.get("plano_id") or "essencial",
        "idade": slots["idade"],
        "veiculo_ano": slots["veiculo_ano"],
    }
    if slots.get("cep"):
        payload["cep"] = slots["cep"]
    if slots.get("data_inicio"):
        payload["data_inicio"] = slots["data_inicio"]
    return payload

from __future__ import annotations
import hashlib
from contextlib import asynccontextmanager
from fastapi import FastAPI, HTTPException
from . import config, storage, llm, quote_client, state_machine, replies
from .models import ConversationState
from .pii import mask_pii
from .schemas import WebhookMessageIn, WebhookMessageOut


@asynccontextmanager
async def _lifespan(app: FastAPI):
    storage.init_db()
    yield


app = FastAPI(title="AutoSeguro Agent", version="1.0.0", lifespan=_lifespan)


def _build_message_id(msg: WebhookMessageIn, masked_body: str) -> str:
    raw = f"{msg.conversation_id}|{msg.sender_role}|{msg.message_type}|{msg.timestamp}|{masked_body}"
    return "msg_" + hashlib.sha256(raw.encode("utf-8")).hexdigest()[:32]


def _finish(message_id: str, reply: str) -> WebhookMessageOut:
    masked_reply = mask_pii(reply)
    storage.save_response(message_id, masked_reply)
    return WebhookMessageOut(message_id=message_id, reply=masked_reply)


***@app.post("/webhook/message", response_model=WebhookMessageOut)
def webhook_message(msg: WebhookMessageIn) -> WebhookMessageOut:
    masked_body = mask_pii(msg.message_body)
    message_id = _build_message_id(msg, masked_body)

    cached = storage.get_message(message_id)
    if cached:
        return WebhookMessageOut(**cached)

    storage.save_message(message_id, msg.conversation_id, msg.sender_role,
                          msg.message_type, masked_body, msg.timestamp)

    state = storage.load_state(msg.conversation_id)

    if state.status == "escalonada":
        return _finish(message_id, replies.ESCALONADA)

    history = storage.recent_messages(msg.conversation_id, config.HISTORY_LIMIT)
    slots_delta, intent = llm.extract_and_classify(history, masked_body)

    decision = state_machine.pre_quote_decision(state, intent, slots_delta)

    if decision.action == "escalar":
        storage.log_escalation(msg.conversation_id, decision.motivo)
        storage.save_state(ConversationState(msg.conversation_id, decision.slots, decision.stagnation_count, "escalonada"))
        return _finish(message_id, replies.ESCALONADA)

    if decision.action == "pedir_dado":
        storage.save_state(ConversationState(msg.conversation_id, decision.slots, decision.stagnation_count, "em_andamento"))
        return _finish(message_id, replies.ask_missing(decision.missing))

    payload = state_machine.build_quote_payload(decision.slots)
    result = quote_client.call_quote(payload)
    for attempt in result.attempts:
        storage.log_quote_attempt(msg.conversation_id, payload, attempt)

    post = state_machine.post_quote_decision(result)

    if post.action == "responder_cotacao":
        storage.save_state(ConversationState(msg.conversation_id, decision.slots, 0, "cotado"))
        return _finish(message_id, replies.quote_success(result.data))

    if post.action == "responder_recusa":
        storage.save_state(ConversationState(msg.conversation_id, decision.slots, 0, "recusado"))
        return _finish(message_id, replies.quote_refusal(result.motivo))

    storage.log_escalation(msg.conversation_id, post.motivo)
    storage.save_state(ConversationState(msg.conversation_id, decision.slots, 0, "escalonada"))
    return _finish(message_id, replies.INSTABILIDADE_ESCALONADA)


