        linhas.append(f"Primeiro pagamento proporcional: R$ {pro_rata['valor_primeiro_pagamento']:.2f}.")
    return " ".join(linhas)


def quote_refusal(motivo: str | None) -> str:
    base = motivo or "Nao consegui aprovar essa cotacao com os dados informados."
